import { useWallet } from '../../providers/WalletProvider';
import { useToast } from '../../providers/ToastProvider';
import { formatVolume, formatAddress, formatCountdown, formatDeadlineDateTime, formatExactUsdl } from '../../../utils/formatters';
import ResolutionRules from '../Shared/ResolutionRules';

interface MarketCardProps {
    market: MarketData;
    onClick: () => void;
    now?: number;
    // Legacy props for backwards compatibility (will be removed)
    title?: string;
    icon?: string;
    probability?: number;
    volume?: number;
    timeLeft?: string;
    trend?: 'up' | 'down';
    type?: 'crypto' | 'stock' | 'other';
    identifier?: string;
}


const CopyIcon = () => (
    <svg
        width="14"
        height="14"
        viewBox="0 0 24 24"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
    >
        <rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" strokeWidth="1.5" />
        <rect x="4" y="4" width="11" height="11" rx="2" stroke="currentColor" strokeWidth="1.5" opacity="0.65" />
    </svg>
);

const MarketCard: React.FC<MarketCardProps> = ({
    market,
    onClick,
    now,
    // Legacy props for backwards compatibility
    title: legacyTitle,
    icon = '≡ƒÆÄ',
    probability: legacyProbability,
    volume: legacyVolume,
    trend = 'up',
    type: legacyType,
    identifier: legacyIdentifier
}) => {
    // Use market data or fall back to legacy props
    const title = market?.title || legacyTitle || 'Market';
    const probability = market ? market.probYes * 100 : (legacyProbability || 50);
    const volume = market?.volume || legacyVolume || 0;
    const type = market?.type || legacyType || 'crypto';
    const identifier = market?.identifier || legacyIdentifier;

    const { isConnected, walletAddress } = useWallet();
    const { showToast } = useToast();

    // Get user market status if we have market data and wallet connected
    const [userStatus, setUserStatus] = React.useState<UserMarketStatus | null>(null);

    React.useEffect(() => {
        const fetchUserStatus = async () => {
            if (market && isConnected && walletAddress && market.contractId) {
                try {
                    const status = await getUserMarketStatus(market.contractId, walletAddress, market);
                    setUserStatus(status);
                } catch (error) {
                    console.error('Error fetching user status:', error);
                    setUserStatus(null);
                }
            } else {
                setUserStatus(null);
            }
        };

        fetchUserStatus();
    }, [market, isConnected, walletAddress]);

    // --- Countdown (simple, using raw end date) ---
    const hasNow = typeof now === 'number';
    const deadlineSeconds = (() => {
        if (!market) return null;
        if (market.deadlineDate) {
            const parsed = Date.parse(market.deadlineDate);
            if (!Number.isNaN(parsed)) return Math.floor(parsed / 1000);
        }
        if (market.deadline !== undefined && market.deadline !== null) {
            const numeric = typeof market.deadline === 'string' ? Number(market.deadline) : market.deadline;
            if (Number.isFinite(numeric)) return numeric;
        }
        return null;
    })();
    const nowSeconds = hasNow ? now! : null;
    const deadlineText = deadlineSeconds !== null ? formatDeadlineDateTime(deadlineSeconds) : null;
    const countdownText = (() => {
        if (deadlineSeconds === null || nowSeconds === null) return null;
        const diffSeconds = deadlineSeconds - nowSeconds;
        if (diffSeconds <= 0) return '0d 0h 0m 0s';
        return formatCountdown(diffSeconds * 1000);
    })();

    React.useEffect(() => {
        if (!market) return;
        console.debug('[MarketCard countdown]', {
            contractId: market.contractId,
            deadlineSeconds,
            nowSeconds,
            diffSeconds: deadlineSeconds !== null && nowSeconds !== null ? deadlineSeconds - nowSeconds : null,
            rawDeadline: market.deadline,
            deadlineDate: market.deadlineDate,
            countdownText
        });
    }, [market, deadlineSeconds, nowSeconds, countdownText]);

    const handleClaim = async (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isConnected) return;
        await claimRewards(market.contractId as `0x${string}`);
    };

    const getActionArea = () => {
        if (!market) {
            // Legacy display
            return (
                <div className={styles.actions}>
                    <span className={`${styles.tag} ${styles.tagYes}`}>YES</span>
                    <span className={`${styles.tag} ${styles.tagNo}`}>NO</span>
                </div>
            );
        }

        if (market.state === 'ACTIVE') {
            return (
                <span className={styles.countdown} title={deadlineText ?? undefined}>
                    {countdownText ?? 'ΓÇö'}
                </span>
            );
        }

        return (
            <span className={styles.deadline} title="Deadline">
                {deadlineText ?? 'ΓÇö'}
            </span>
        );
    };

    const isResolving = market?.state === 'RESOLVING';
    const isFinalized = market?.state === 'RESOLVED' || market?.state === 'UNDETERMINED';

    return (
        <div className={`${styles.card} ${isResolving ? styles.cardResolving : ''} ${isFinalized ? styles.cardFinalized : ''}`} onClick={onClick}>
            <div className={styles.header}>
                <div className={styles.headerLeft}>
                    <span className={styles.icon}>{icon}</span>
                    <div className={styles.titleGroup}>
                        <h3 className={styles.title}>{title}</h3>
                        {market?.contractId && (
                            <div className={styles.addressRow}>
                                <span className={styles.addressText}>{formatAddress(market.contractId)}</span>
                                <button
                                    className={styles.copyBtn}
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        navigator.clipboard?.writeText(market.contractId);
                                        showToast('Address copied', 'success');
                                    }}
                                    aria-label="Copy contract address"
                                >
                                    <CopyIcon />
                                </button>
                            </div>
                        )}
                    </div>
                </div>
                <div style={{ flexShrink: 0, display: 'flex', alignItems: 'center' }}>
                    <ProbabilityGauge probability={probability} market={market} />
                </div>
            </div>

            {isResolving || isFinalized || market?.statsLoading ? (
                <div className={styles.graphContainer}>
                    {market?.statsLoading ? (
                        <div className={styles.statsSkeleton}>
                            <div className={styles.skeletonBar}></div>
                        </div>
                    ) : isResolving ? (
                        <div className={styles.resolvingStage}>
                            <div className={styles.resolvingBackdrop} aria-hidden="true">
                                <svg className={styles.graphLine} viewBox="0 0 100 40" preserveAspectRatio="none">
                                    <path
                                        d="M0,28 C18,30 28,10 46,14 S74,34 100,10"
                                        fill="none"
                                        stroke="rgba(39, 39, 42, 0.55)"
                                        strokeWidth="2"
                                    />
                                    <path
                                        d="M0,35 L0,40 L100,40 L100,18 C80,22 68,34 52,28 S22,18 0,24 Z"
                                        fill="rgba(39, 39, 42, 0.12)"
                                    />
                                </svg>
                            </div>
                            <div className={styles.resolvingOverlay}>
                                <div className={styles.resolvingTitle}>Resolving</div>
                                <div className={styles.resolvingMeta}>
                                    <div className={styles.resolvingRow}>
                                        <span className={styles.resolvingLabel}>Deadline</span>
                                        <span className={styles.resolvingValue}>{deadlineText}</span>
                                    </div>
                                    <div className={styles.resolvingRow}>
                                        <span className={styles.resolvingLabel}>Rule</span>
                                        <span className={`${styles.resolvingValue} ${styles.resolvingRule}`}>
                                            <ResolutionRules market={market} variant="inline" showTitle={false} />
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ) : (
                        (() => {
                            const outcomeTone =
                                market.resolvedOutcome === market.sideAName
                                    ? 'yes'
                                    : market.resolvedOutcome === market.sideBName
                                        ? 'no'
                                        : market.resolvedOutcome === 'INVALID'
                                            ? 'invalid'
                                            : 'neutral';

                            const finalPrice =
                                market.deadlinePrice !== undefined
                                    ? `${market.priceSymbol ?? ''}${market.deadlinePrice.toLocaleString()}`
                                    : null;

                            const position = userStatus?.position;
                            const userState = !userStatus?.hasPosition
                                ? 'none'
                                : userStatus.userWon
                                    ? userStatus.position?.claimed
                                        ? 'claimed'
                                        : userStatus.canClaim
                                            ? 'claimable'
                                            : 'won'
                                    : 'lost';

                            const userLine =
                                userState === 'none'
                                    ? 'No position'
                                    : 'Your stake';

                            const userSubline =
                                userState === 'none'
                                    ? 'You did not participate'
                                    : userState === 'lost'
                                        ? position
                                            ? `${formatVolume(position.amount)} on ${position.outcome}`
                                            : null
                                        : userStatus
                                            ? `+${formatExactUsdl(userStatus.potentialWinnings)}`
                                            : null;

                            return (
                                <div className={styles.finalizedCenter}>
                                    <div className={styles.marketOutcome}>
                                        <div className={styles.marketOutcomeLabel}>Resolved</div>
                                        <div
                                            className={`${styles.marketOutcomeValue} ${
                                                outcomeTone === 'yes'
                                                    ? styles.marketOutcomeYes
                                                    : outcomeTone === 'no'
                                                        ? styles.marketOutcomeNo
                                                        : outcomeTone === 'invalid'
                                                            ? styles.marketOutcomeInvalid
                                                            : styles.marketOutcomeNeutral
                                            }`}
                                        >
                                            {market.resolvedOutcome ?? 'ΓÇö'}
                                        </div>
                                    </div>

                                    <div className={styles.marketFacts}>
                                        <div className={styles.fact}>
                                            <span className={styles.factLabel}>Closed at</span>
                                            <span className={styles.factValue}>{finalPrice ?? 'ΓÇö'}</span>
                                        </div>
                                    </div>

                                    <div className={styles.userOutcome}>
                                        {!isConnected ? (
                                            <div className={styles.userOutcomeText}>
                                                <div className={`${styles.userOutcomeLine} ${styles.userOutcomeNeutral}`}>
                                                    Your stake
                                                </div>
                                                <div className={styles.userOutcomeSubline}>
                                                    Connect your wallet to start betting.
                                                </div>
                                            </div>
                                        ) : (
                                            <>
                                                <div className={styles.userOutcomeText}>
                                                    <div className={`${styles.userOutcomeLine} ${styles.userOutcomeNeutral}`}>
                                                        {userLine}
                                                    </div>
                                                    {userSubline && (
                                                        <div
                                                            className={
                                                                userState === 'claimable' || userState === 'won' || userState === 'claimed'
                                                                    ? styles.userOutcomePayout
                                                                    : styles.userOutcomeSubline
                                                            }
                                                        >
                                                            {userSubline}
                                                        </div>
                                                    )}
                                                </div>

                                                {userState === 'claimable' ? (
                                                    <button className={`${styles.claimButton} ${styles.claimButtonShimmer}`} onClick={handleClaim}>
                                                        Claim
                                                    </button>
                                                ) : userState === 'claimed' ? (
                                                    <span className={`${styles.claimButton} ${styles.claimButtonClaimed}`}>
                                                        Claimed
                                                    </span>
                                                ) : null}
                                            </>
                                        )}
                                    </div>
                                </div>
                            );
                        })()
                    )}
                </div>
            ) : (
                <div style={{ flex: 1 }}></div>
            )}

            <div className={styles.footer}>
                <div className={styles.footerLeft}>
                    {market?.statsLoading ? (
                        <span className={styles.volumeLoading}></span>
                    ) : (
                        <span className={styles.volume}>{formatVolume(volume)}</span>
                    )}
                </div>
                {getActionArea()}
            </div>
        </div>
    );
};

export default MarketCard;

import React from 'react';
import styles from './MarketFullPage.module.css';
import TradeBox from '../SharedMarket/TradeBox';
import UserBetDisplay from '../SharedMarket/UserBetDisplay';
import ChartSection from '../SharedMarket/ChartSection';
import { MarketData, getUserMarketStatus, UserMarketStatus } from '../../../data/markets';
import { claimRewards } from '../../../lib/onchain/writes';
import { useWallet } from '../../providers/WalletProvider';
import { useToast } from '../../providers/ToastProvider';
import ConnectWalletPrompt from '../Wallet/ConnectWalletPrompt';
import { formatVolume, formatAddress, formatResolutionDate } from '../../../utils/formatters';
import CopyIcon from '../Shared/CopyIcon';
import ResolutionRules from '../Shared/ResolutionRules';
import { useLiveScore } from '../../../hooks/useLiveScore';

interface MarketFullPageProps {
    onBack: () => void;
    market?: MarketData; // New: Full market data
    // Legacy props for backwards compatibility
    marketTitle?: string;
    probability?: number;
    type?: 'crypto' | 'stock' | 'sport' | 'politics' | 'other';
    identifier?: string;
    description?: string;
    resolutionRule?: string;
    volume?: number;
}


const MarketFullPage: React.FC<MarketFullPageProps> = ({
    onBack,
    market,
    // Legacy props
    marketTitle: legacyTitle = "Market Title",
    probability: legacyProbability = 50,
    type: legacyType = 'crypto',
    identifier: legacyIdentifier = 'bitcoin',
    description: legacyDescription = "",
    resolutionRule: legacyResolutionRule = "Standard Rules",
    volume: legacyVolume = 0
}) => {
    // Use market data or fall back to legacy props
    const marketTitle = market?.title || legacyTitle;
    const probability = market ? market.probYes * 100 : legacyProbability;
    const type = market?.type || legacyType;
    const identifier = market?.identifier || legacyIdentifier;
    const description = market?.description || legacyDescription;
    const resolutionRule = market?.resolutionRule || legacyResolutionRule;
    const volume = market?.volume || legacyVolume;

    const { isConnected, walletAddress } = useWallet();
    const { showToast } = useToast();
    const isSportsMarket = market?.category === 'SPORTS' || type === 'sport';
    const { liveScore, loading: liveScoreLoading } = useLiveScore(
        isSportsMarket ? market?.sideAName : undefined,
        isSportsMarket ? market?.sideBName : undefined,
        market?.deadlineDate ?? market?.deadline
    );

    // Get user status for finalized markets
    const [userStatus, setUserStatus] = React.useState<UserMarketStatus | null>(null);

    React.useEffect(() => {
        const fetchUserStatus = async () => {
            if (market && isConnected && walletAddress && market.contractId) {
                try {
                    const status = await getUserMarketStatus(market.contractId, walletAddress, market);
                    setUserStatus(status);
                } catch (error) {
                    console.error('Error fetching user status:', error);
                    setUserStatus(null);
                }
            } else {
                setUserStatus(null);
            }
        };

        fetchUserStatus();
    }, [market, isConnected, walletAddress]);
    const finalPriceText = market?.deadlinePrice
        ? `${market.priceSymbol ?? ''}${market.deadlinePrice.toLocaleString()}`
        : null;
    const resolutionDate = formatResolutionDate(market?.deadlineDate);
    const handleClaim = async () => {
        if (!market || !isConnected) return;
        await claimRewards(market.contractId as `0x${string}`);
    };

    // Shared rendering functions
    const renderTopBar = () => (
        <div className={styles.topBar}>
            <button className={styles.backButton} onClick={onBack}>ΓåÉ Back</button>
            <button className={styles.backButton}>Share</button>
        </div>
    );

    const renderMetaRow = () => {
        const state = market?.state || 'ACTIVE';
        const isResolved = state === 'RESOLVED' || state === 'UNDETERMINED';
        const dateText = isResolved
            ? 'Trading closed'
            : `Ends on ${formatResolutionDate(market?.deadlineDate ?? market?.deadline) ?? 'ΓÇö'}`;

        return (
            <div className={styles.metaRow}>
                <span>{dateText}</span>
                {market?.contractId && (
                    <span>
                        {formatAddress(market.contractId)}
                        <button
                            className={styles.copyButton}
                            onClick={() => {
                                navigator.clipboard?.writeText(market.contractId);
                                showToast('Address copied', 'success');
                            }}
                            aria-label="Copy contract address"
                        >
                            <CopyIcon />
                        </button>
                    </span>
                )}
            </div>
        );
    };

    const renderStateRow = () => {
        const state = market?.state || 'ACTIVE';

        if (state === 'UNDETERMINED') {
            return (
                <div className={styles.stateRow}>
                    <span className={`${styles.statePill} ${styles.statePillUndetermined}`}>Undetermined</span>
                    <span className={styles.stateNote}>Trading closed ┬╖ Outcome undetermined</span>
                </div>
            );
        } else if (state === 'RESOLVED') {
            return (
                <div className={styles.stateRow}>
                    <span className={`${styles.statePill} ${styles.statePillFinalized}`}>Finalized</span>
                    <span className={styles.stateNote}>Trading closed ┬╖ Outcome locked</span>
                </div>
            );
        } else if (state === 'RESOLVING') {
            return (
                <div className={styles.stateRow}>
                    <span className={`${styles.statePill} ${styles.statePillResolving}`}>Resolving</span>
                    <span className={styles.stateNote}>Trading paused ┬╖ Outcome pending</span>
                </div>
            );
        } else {
            return (
                <div className={styles.stateRow}>
                    <span className={`${styles.statePill} ${styles.statePillActive}`}>Active</span>
                    <span className={styles.stateNote}>Trading open ┬╖ Live market</span>
                </div>
            );
        }
    };

    const renderTitle = () => (
        <h1 className={styles.title}>{marketTitle}</h1>
    );

    const renderLiveScoreCard = () => {
        if (!isSportsMarket) return null;

        const kickoffText = formatResolutionDate(liveScore?.utcDate ?? market?.deadlineDate ?? market?.deadline);
        const status = liveScore?.status ?? 'SCHEDULED';
        const isNotStarted = status === 'TIMED' || status === 'SCHEDULED' || !liveScore;
        const statusLabel = liveScoreLoading
            ? 'Loading score'
            : isNotStarted
                ? 'Not Started'
                : liveScore?.elapsed || status;
        const homeGoals = liveScore?.homeGoals ?? 0;
        const awayGoals = liveScore?.awayGoals ?? 0;

        return (
            <section className={styles.liveScoreCard} aria-label="Live match score">
                <div className={styles.liveScoreHeader}>
                    <span className={styles.liveScoreEyebrow}>Match Center</span>
                    <span className={`${styles.liveStatusPill} ${!isNotStarted ? styles.liveStatusPillActive : ''}`}>
                        {statusLabel}
                    </span>
                </div>
                <div className={styles.scoreboardRow}>
                    <div className={styles.scoreTeam}>
                        <span className={styles.teamName}>{liveScore?.homeTeam || market?.sideAName || 'Home'}</span>
                        <span className={styles.scoreValue}>{isNotStarted ? 'ΓÇö' : homeGoals}</span>
                    </div>
                    <div className={styles.scoreDivider}>vs</div>
                    <div className={styles.scoreTeam}>
                        <span className={styles.teamName}>{liveScore?.awayTeam || market?.sideBName || 'Away'}</span>
                        <span className={styles.scoreValue}>{isNotStarted ? 'ΓÇö' : awayGoals}</span>
                    </div>
                </div>
                <div className={styles.kickoffMeta}>Kickoff: {kickoffText || 'ΓÇö'}</div>
            </section>
        );
    };

    const renderProgressBar = () => {
        if (market?.category === 'SPORTS') {
            const probYes = market.probYes * 100;
            const probDraw = (market.probDraw ?? 0) * 100;
            const probNo = market.probNo * 100;
            return (
                <div className={`${styles.progressSection} ${styles.sportsProgressSection}`}>
                    <div className={styles.sportsProbabilityText}>
                        <span className={styles.sportsProbYes}>{probYes.toFixed(1)}%</span>
                        <span className={styles.sportsProbDraw}>{probDraw.toFixed(1)}%</span>
                        <span className={styles.sportsProbNo}>{probNo.toFixed(1)}%</span>
                    </div>
                    <div className={styles.sportsBarBackground}>
                        <div className={styles.sportsBarYes} style={{ flexGrow: Math.max(probYes, 0.01) }}></div>
                        <div className={styles.sportsBarDraw} style={{ flexGrow: Math.max(probDraw, 0.01) }}></div>
                        <div className={styles.sportsBarNo} style={{ flexGrow: Math.max(probNo, 0.01) }}></div>
                    </div>
                    <div className={styles.sportsOutcomeLabels}>
                        <span title={market?.sideAName ?? 'Home'}>{market?.sideAName ?? 'Home'}</span>
                        <span title={market?.drawName ?? 'Draw'}>{market?.drawName ?? 'Draw'}</span>
                        <span title={market?.sideBName ?? 'Away'}>{market?.sideBName ?? 'Away'}</span>
                    </div>
                </div>
            );
        }

        return (
            <div className={styles.progressSection}>
                <div className={styles.probabilityText}>
                    <span style={{ color: 'var(--foreground)' }}>{probability.toFixed(1)}%</span>
                    <span style={{ color: 'var(--text-secondary)' }}>{(100 - probability).toFixed(1)}%</span>
                </div>
                <div className={styles.barBackground}>
                    <div className={styles.barFill} style={{ width: `${probability}%` }}></div>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '4px' }}>
                    <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{market?.sideAName ?? 'Side A'}</span>
                    <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{market?.sideBName ?? 'Side B'}</span>
                </div>
            </div>
        );
    };

    const renderVolumeRow = () => (
        <div className={styles.volumeRow}>
            <span>Γåù Volume {formatVolume(volume)}</span>
        </div>
    );

    const renderTruthBlock = () => {
        const state = market?.state || 'ACTIVE';
        const isResolved = state === 'RESOLVED' || state === 'UNDETERMINED';
        const isResolving = state === 'RESOLVING';

        if (!isResolved && !isResolving) return null;


        return (
            <div className={styles.truthBlock}>
                <div className={styles.truthHeader}>Resolution</div>
                <div className={styles.truthOutcomeRow}>
                    {isResolving ? (
                        <div className={`${styles.truthOutcome} ${styles.truthOutcomeNeutral}`}>
                            Resolving<span className={styles.truthEllipsis}>...</span>
                        </div>
                    ) : (
                        <>
                            <div
                                className={`${styles.truthOutcome} ${
                                    market?.resolvedOutcome === market?.sideAName
                                        ? styles.truthOutcomeYes
                                        : market?.resolvedOutcome === market?.sideBName
                                            ? styles.truthOutcomeNo
                                            : styles.truthOutcomeNeutral
                                }`}
                            >
                                {market?.resolvedOutcome ?? 'ΓÇö'}
                            </div>
                            <div className={styles.truthValue}>
                                {finalPriceText ? `At ${finalPriceText}` : 'Value unavailable'}
                            </div>
                        </>
                    )}
                </div>
                <div className={styles.truthMeta}>
                    <div className={styles.truthMetaItem}>
                        <span className={styles.truthMetaLabel}>Condition</span>
                        <span className={styles.truthMetaValue}>{description}</span>
                    </div>
                    {resolutionDate && (
                        <div className={styles.truthMetaItem}>
                            <span className={styles.truthMetaLabel}>
                                {isResolving ? 'Expected' : 'Resolved on'}
                            </span>
                            <span className={styles.truthMetaValue}>{resolutionDate}</span>
                        </div>
                    )}
                </div>
            </div>
        );
    };

    const renderFinishedMarketContent = () => (
        <>
            {market && <ResolutionRules market={market} />}
        </>
    );

    const renderResolvingMarketContent = () => (
        <>
            {market && <ResolutionRules market={market} />}
        </>
    );

    const renderActiveMarketContent = () => (
        <>
            <ChartSection probability={probability} type={type} identifier={identifier} market={market} />
            {market && <ResolutionRules market={market} />}
        </>
    );

    const renderFinishedMarketSidebar = () => (
        <div className={styles.sidebar}>
            <div className={styles.userResultsSection}>
                <h3 className={styles.sectionTitle}>Your Result</h3>
                {!isConnected ? (
                    <ConnectWalletPrompt
                        align="left"
                        message="Connect your wallet to start betting."
                    />
                ) : !userStatus?.hasPosition ? (
                    <div className={styles.noPositionCard}>
                        <div className={styles.cardHeader}>No Position Taken</div>
                        <p>You did not place a bet on this market.</p>
                    </div>
                ) : (
                    <div className={styles.positionResultCard}>
                        <div className={styles.betSummary}>
                            <span className={styles.betLabel}>Your Bet:</span>
                            <span className={styles.betDetails}>
                                {formatVolume(userStatus.position!.amount)} on {userStatus.position!.outcome}
                            </span>
                        </div>

                        <div className={`${styles.outcomeResult} ${
                            userStatus.userWon ? styles.resultWin : styles.resultLoss
                        }`}>
                            {userStatus.userWon ? (
                                <>
                                    <div className={styles.winMessage}>You Won!</div>
                                    <div className={styles.winAmount}>
                                        +{formatVolume(userStatus.potentialWinnings)}
                                    </div>
                                    {userStatus.canClaim ? (
                                        <button className={styles.claimButton} onClick={handleClaim}>
                                            Claim Winnings
                                        </button>
                                    ) : (
                                        <div className={styles.claimedStatus}>
                                            Γ£ô Winnings Claimed
                                        </div>
                                    )}
                                </>
                            ) : (
                                <>
                                    <div className={styles.lossMessage}>You Lost</div>
                                    <div className={styles.lossAmount}>
                                        -{formatVolume(userStatus.position!.amount)}
                                    </div>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );

    const renderResolvingMarketSidebar = () => (
        <div className={styles.sidebar}>
            {market && <UserBetDisplay market={market} variant="full" />}
        </div>
    );

    const renderActiveMarketSidebar = () => (
        <div className={styles.sidebar}>
            <TradeBox probability={probability} market={market} />
            {market && <UserBetDisplay market={market} variant="full" />}
        </div>
    );

    const state = market?.state || 'ACTIVE';
    const isActive = state === 'ACTIVE';

    return (
        <div className={styles.wrap}>
            <div className={styles.container}>
                <div className={styles.mainContent}>
                    {renderTopBar()}
                    {isActive && renderMetaRow()}
                    {renderTitle()}
                    {renderLiveScoreCard()}
                    {renderStateRow()}

                    {/* Truth block for resolved/undetermined markets comes before progress bar */}
                    {(state === 'RESOLVED' || state === 'UNDETERMINED') && renderTruthBlock()}

                    {/* Progress bar and volume for all non-resolved markets */}
                    {state !== 'RESOLVED' && state !== 'UNDETERMINED' && (
                        <>
                            {renderProgressBar()}
                            {renderVolumeRow()}
                        </>
                    )}

                    {/* Truth block for resolving markets comes after progress bar */}
                    {state === 'RESOLVING' && renderTruthBlock()}

                    {/* State-specific content */}
                    {(state === 'RESOLVED' || state === 'UNDETERMINED') && renderFinishedMarketContent()}
                    {state === 'RESOLVING' && renderResolvingMarketContent()}
                    {isActive && renderActiveMarketContent()}
                </div>

                {/* State-specific sidebars */}
                {(state === 'RESOLVED' || state === 'UNDETERMINED') && renderFinishedMarketSidebar()}
                {state === 'RESOLVING' && renderResolvingMarketSidebar()}
                {isActive && renderActiveMarketSidebar()}
            </div>
        </div>
    );
};

export default MarketFullPage;

"use client";

import { useEffect, useRef, useState, useMemo, useCallback } from "react";

interface PricePoint {
    time: number;
    value: number;
}

interface BtcChartProps {
    symbol?: string;
    height?: number;
    startTime?: number;
    endTime?: number;
    bettingEndTime?: number;
    strikePrice?: number;
}

// ΓöÇΓöÇ LocalStorage price cache (fills CCXT lag gap across page refreshes) ΓöÇΓöÇ
const LS_KEY = 'btc_rt_cache';
const LS_MAX_HOURS = 2;

function loadStoredPrices(): PricePoint[] {
    try {
        if (typeof window === 'undefined') return [];
        const raw = localStorage.getItem(LS_KEY);
        if (!raw) return [];
        const data = JSON.parse(raw) as PricePoint[];
        const cutoff = Math.floor(Date.now() / 1000) - LS_MAX_HOURS * 3600;
        return data.filter(p => p.time > cutoff);
    } catch { return []; }
}

function savePrice(point: PricePoint) {
    try {
        if (typeof window === 'undefined') return;
        const stored = loadStoredPrices();
        // Deduplicate within 14s window, keep last 480 points
        const updated = [...stored.filter(p => p.time < point.time - 14), point].slice(-480);
        localStorage.setItem(LS_KEY, JSON.stringify(updated));
    } catch { }
}

export function BtcChart({ symbol = "BTCUSDT", height = 480, startTime, endTime, bettingEndTime, strikePrice }: BtcChartProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const [width, setWidth] = useState(0);
    const [history, setHistory] = useState<PricePoint[]>([]);
    const [livePrice, setLivePrice] = useState<number | null>(null);
    // Binance WebSocket candles ΓÇö fills CCXT lag gap with real data
    const [wsCandles, setWsCandles] = useState<PricePoint[]>([]);

    // Interactive state
    const [hoverPoint, setHoverPoint] = useState<PricePoint | null>(null);
    const [mousePos, setMousePos] = useState<{ x: number; y: number } | null>(null);

    const actualBettingEndTime = bettingEndTime || (endTime ? endTime - 900 : undefined);

    // We reserve space on the right for the price axis/labels
    const RIGHT_AXIS_WIDTH = 75;

    useEffect(() => {
        if (!containerRef.current) return;
        const observer = new ResizeObserver((entries) => {
            for (const entry of entries) {
                setWidth(entry.contentRect.width);
            }
        });
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        let isMounted = true;
        async function fetchHistory() {
            if (!startTime || !endTime) return;
            try {
                const res = await fetch(`/api/history?since=${startTime - 600}`, { cache: "no-store" });
                if (!res.ok) throw new Error("History API failed");
                const data = await res.json();
                const raw = data.history || [];
                const currentNow = Math.floor(Date.now() / 1000);

                const filtered = raw
                    .filter((p: any) => p.time >= (startTime - 3600) && p.time <= Math.min(endTime, currentNow + 60))
                    .sort((a: any, b: any) => a.time - b.time);

                if (isMounted) setHistory(filtered);
            } catch (err) {
                console.error("SVG Chart history error:", err);
            }
        }
        fetchHistory();
        const t = setInterval(fetchHistory, 60000); // 60s ΓÇö history is 1-min candles, no need to poll faster
        return () => { isMounted = false; clearInterval(t); };
    }, [startTime, endTime]);

    useEffect(() => {
        let isMounted = true;
        async function fetchLive() {
            try {
                const res = await fetch("/api/price", { cache: "no-store" });
                if (res.ok && isMounted) {
                    const data = await res.json();
                    if (data.price > 0) setLivePrice(data.price);
                }
            } catch (k) { }
        }
        fetchLive();
        const t = setInterval(fetchLive, 2000);
        return () => { isMounted = false; clearInterval(t); };
    }, [endTime, startTime]);

    // ΓöÇΓöÇ Binance REST: fill gap between CCXT history end and now ΓöÇΓöÇ
    useEffect(() => {
        if (!startTime || !endTime) return;
        let isMounted = true;
        async function fillGap() {
            const now = Math.floor(Date.now() / 1000);
            const limitMinutes = Math.min(Math.floor((now - startTime!) / 60) + 30, 1000);
            try {
                const res = await fetch(
                    `https://api.binance.com/api/v3/klines?symbol=BTCUSDT&interval=1m&limit=${limitMinutes}`,
                    { cache: 'no-store' }
                );
                if (!res.ok) return;
                const raw: any[][] = await res.json();
                const candles: PricePoint[] = raw.map(k => ({
                    time: Math.floor(k[0] / 1000),
                    value: parseFloat(k[4]), // close price
                })).filter(p => p.time >= startTime! && p.time <= endTime!);
                if (isMounted) setWsCandles(candles);
            } catch { }
        }
        fillGap();
        // Refresh every 60s to pick up newly closed candles
        const t = setInterval(fillGap, 60000);
        return () => { isMounted = false; clearInterval(t); };
    }, [startTime, endTime]);

    // ΓöÇΓöÇ Binance WebSocket: update current (open) candle in real-time ΓöÇΓöÇ
    useEffect(() => {
        if (!startTime || !endTime) return;
        const now = Math.floor(Date.now() / 1000);
        if (now > endTime!) return; // don't connect after market ends
        const ws = new WebSocket('wss://stream.binance.com:9443/ws/btcusdt@kline_1m');
        ws.onmessage = (event) => {
            try {
                const data = JSON.parse(event.data);
                const k = data.k;
                if (!k) return;
                const klineStart = Math.floor(Number(k.t) / 1000);
                const closePrice = parseFloat(k.c);
                if (klineStart < startTime! || klineStart > endTime!) return;
                setWsCandles(prev => {
                    const filtered = prev.filter(p => p.time !== klineStart);
                    return [...filtered, { time: klineStart, value: closePrice }]
                        .sort((a, b) => a.time - b.time);
                });
            } catch { }
        };
        ws.onerror = () => ws.close();
        return () => ws.close();
    }, [startTime, endTime]);

    const allPoints = useMemo(() => {
        const now = Math.floor(Date.now() / 1000);
        // Merge CCXT history with Binance candles (CCXT = 1h+ ago, Binance = recent gap)
        const combined = new Map<number, number>();
        history.forEach(p => combined.set(p.time, p.value));
        wsCandles.forEach(p => combined.set(p.time, p.value)); // Binance overwrites where overlap
        const merged = Array.from(combined.entries())
            .map(([time, value]) => ({ time, value }))
            .filter(p => p.time >= (startTime ?? 0) && p.time <= Math.min(endTime ?? now, now))
            .sort((a, b) => a.time - b.time);

        // Always append current live dot (median 10 CEX)
        const lastTime = merged.length > 0 ? merged[merged.length - 1].time : 0;
        if (livePrice && startTime && now <= (endTime ?? now + 1) && now > lastTime) {
            merged.push({ time: now, value: livePrice });
        }
        return merged;
    }, [history, wsCandles, livePrice, startTime, endTime]);

    const scale = useMemo(() => {
        if (!startTime || !endTime || !width || !strikePrice) return null;

        const prices = allPoints.map(p => p.value);
        const midP = strikePrice;

        // Calculate symmetric range centering strikePrice
        const maxDelta = prices.length > 0 ? Math.max(...prices.map(p => Math.abs(p - midP))) : 50;
        // Buffer: always fit all data points + 15% padding, with 1% minimum of strikePrice
        // Do NOT cap at 5% ΓÇö price can move 10%+ on daily/weekly markets
        const rawBuffer = Math.max(maxDelta * 1.15, midP * 0.01);
        const buffer = rawBuffer;


        const minScale = midP - buffer;
        const maxScale = midP + buffer;

        // Map time to width minus the reserved price axis area
        const availableWidth = width - RIGHT_AXIS_WIDTH;
        const getX = (t: number) => ((t - startTime) / (endTime - startTime)) * availableWidth;

        const paddingY = 70;
        const chartAreaH = height - paddingY * 2 - 40;
        const getY = (p: number) => paddingY + chartAreaH - ((p - minScale) / (maxScale - minScale)) * chartAreaH;

        return { getX, getY, minScale, maxScale, midP, strikeY: getY(midP), availableWidth };
    }, [allPoints, startTime, endTime, width, height, strikePrice, RIGHT_AXIS_WIDTH]);

    const paths = useMemo(() => {
        if (!scale || allPoints.length === 0) return null;

        let d = `M ${scale.getX(allPoints[0].time)} ${scale.getY(allPoints[0].value)}`;
        for (let i = 1; i < allPoints.length; i++) {
            const x = scale.getX(allPoints[i].time);
            const y = scale.getY(allPoints[i].value);
            if (!isNaN(x) && !isNaN(y)) {
                d += ` L ${x} ${y}`;
            }
        }

        const lastX = scale.getX(allPoints[allPoints.length - 1].time);
        const lastY = scale.getY(allPoints[allPoints.length - 1].value);

        return { mainPath: d, lastX, lastY };
    }, [allPoints, scale]);

    const handleMouseMove = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
        if (!scale || allPoints.length === 0 || !containerRef.current) return;

        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        // Limit interaction to the chart area (not the axis)
        if (x > scale.availableWidth) return;

        let nearest = allPoints[0];
        let minDist = Math.abs(scale.getX(allPoints[0].time) - x);

        for (let i = 1; i < allPoints.length; i++) {
            const dist = Math.abs(scale.getX(allPoints[i].time) - x);
            if (dist < minDist) {
                minDist = dist;
                nearest = allPoints[i];
            }
        }

        setHoverPoint(nearest);
        setMousePos({ x, y });
    }, [allPoints, scale]);

    const handleMouseLeave = useCallback(() => {
        setHoverPoint(null);
        setMousePos(null);
    }, []);

    if (!startTime || !endTime || !strikePrice) return null;

    const isAbove = livePrice !== null && strikePrice !== undefined && livePrice > strikePrice;

    return (
        <div ref={containerRef} style={{
            display: "flex", flexDirection: "column", width: "100%", height: `${height}px`,
            background: "#0a0a0a", borderRadius: "12px", border: "1px solid rgba(255,255,255,0.05)",
            position: "relative", overflow: "hidden"
        }}>
            {/* Header UI */}
            <div style={{
                position: "absolute", top: "16px", left: "20px", right: "20px",
                display: "flex", justifyContent: "space-between", alignItems: "center",
                zIndex: 50, pointerEvents: "none"
            }}>
                <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                    <span style={{ fontSize: "14px", fontWeight: 700, color: "#fff" }}>{symbol.replace("USDT", "/USD")}</span>
                    <span style={{ fontSize: "14px", color: "rgba(255,255,255,0.2)" }}>ΓÇó</span>
                    <span style={{ fontSize: "10px", color: "#9cfc0d", fontWeight: 700 }}>LIVE</span>
                    <span style={{
                        fontSize: "10px",
                        background: isAbove ? "rgba(156,252,13,0.1)" : "rgba(255, 45, 85, 0.1)",
                        color: isAbove ? "#9cfc0d" : "#ff375f",
                        padding: "3px 8px", borderRadius: "4px", fontWeight: 900,
                        border: isAbove ? "1px solid rgba(156,252,13,0.3)" : "1px solid rgba(255, 45, 85, 0.3)"
                    }}>
                        {isAbove ? "ABOVE" : "BELOW"}
                    </span>
                </div>

                <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
                    <div style={{ fontSize: "13px" }}>
                        <span style={{ color: "rgba(255,255,255,0.6)", fontWeight: 500 }}>Current</span> <span style={{ fontFamily: "monospace", color: "#fff", fontWeight: 800, fontSize: "16px" }}>${livePrice?.toLocaleString(undefined, { minimumFractionDigits: 3 })}</span>
                    </div>
                </div>
            </div>

            {width > 0 && scale && (
                <svg
                    width={width}
                    height={height}
                    style={{ display: "block", cursor: "crosshair" }}
                    onMouseMove={handleMouseMove}
                    onMouseLeave={handleMouseLeave}
                >
                    <defs>
                        <linearGradient id="greenFill" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#9cfc0d" stopOpacity="0.1" />
                            <stop offset="100%" stopColor="#9cfc0d" stopOpacity="0" />
                        </linearGradient>
                        <linearGradient id="redFill" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#ff375f" stopOpacity="0" />
                            <stop offset="100%" stopColor="#ff375f" stopOpacity="0.1" />
                        </linearGradient>

                        <clipPath id="clipTop">
                            <rect x="0" y="0" width={scale.availableWidth} height={scale.strikeY} />
                        </clipPath>
                        <clipPath id="clipBottom">
                            <rect x="0" y={scale.strikeY} width={scale.availableWidth} height={height - scale.strikeY} />
                        </clipPath>
                    </defs>

                    {/* Horizontal Grid & Price Labels (Axis stays fixed on right padding) */}
                    {[0, 0.25, 0.5, 0.75, 1].map((f, i) => {
                        const y = 70 + f * (height - 180);
                        const price = scale.maxScale - f * (scale.maxScale - scale.minScale);
                        return (
                            <g key={i}>
                                <line x1="0" y1={y} x2={scale.availableWidth} y2={y} stroke="rgba(255,255,255,0.03)" />
                                <text x={width - 10} y={y + 3} textAnchor="end" fill="rgba(255,255,255,0.15)" fontSize="9" fontFamily="monospace">
                                    {Math.round(price)}
                                </text>
                            </g>
                        );
                    })}

                    {/* Time Labels (Bottom Axis) */}
                    {[startTime, Math.floor((startTime + endTime) / 2), endTime].map((t, i) => {
                        const x = scale.getX(t);
                        const date = new Date(t * 1000);
                        const h = date.getUTCHours().toString().padStart(2, '0');
                        const m = date.getUTCMinutes().toString().padStart(2, '0');
                        return (
                            <text key={i} x={x} y={height - 25} textAnchor={i === 0 ? "start" : i === 2 ? "end" : "middle"} fill="rgba(255,255,255,0.3)" fontSize="10" fontFamily="monospace">
                                {`${h}:${m}`}
                            </text>
                        );
                    })}

                    {/* TARGET PRICE LINE */}
                    <line x1="0" y1={scale.strikeY} x2={width} y2={scale.strikeY} stroke="#00ccff" strokeDasharray="4 4" strokeWidth="1" />
                    <rect x={width - 65} y={scale.strikeY - 7} width="65" height="14" fill="#00ccff" rx="2" />
                    <text x={width - 32} y={scale.strikeY + 3} textAnchor="middle" fill="#000" fontSize="8.5" fontWeight="950" fontFamily="monospace">
                        {strikePrice?.toFixed(2)}
                    </text>
                    <text x={width - 7} y={scale.strikeY - 11} textAnchor="end" fill="#00ccff" fontSize="8" fontWeight="800">Target</text>

                    {/* Vertical Betting Closes Marker */}
                    {actualBettingEndTime && (
                        <g>
                            <line x1={scale.getX(actualBettingEndTime)} y1="0" x2={scale.getX(actualBettingEndTime)} y2={height - 60} stroke="rgba(245, 158, 11, 0.4)" strokeDasharray="3 3" />
                            <text
                                x={scale.getX(actualBettingEndTime)}
                                y={height - 45}
                                textAnchor="middle"
                                fill="#f59e0b"
                                fontSize="10"
                                fontFamily="monospace"
                                fontWeight="700"
                            >
                                {(() => {
                                    const d = new Date(actualBettingEndTime * 1000);
                                    return `${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`;
                                })()}
                            </text>
                            <text
                                x={scale.getX(actualBettingEndTime)}
                                y={height - 35}
                                textAnchor="middle"
                                fill="rgba(245, 158, 11, 0.6)"
                                fontSize="8"
                                fontFamily="sans-serif"
                                fontWeight="900"
                            >
                                BETTING CLOSE TIME
                            </text>
                        </g>
                    )}

                    {/* Price Line Rendering */}
                    {paths && (
                        <>
                            {/* Above Path */}
                            <g clipPath="url(#clipTop)">
                                <path d={paths.mainPath} fill="none" stroke="#9cfc0d" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d={`${paths.mainPath} L ${paths.lastX} ${scale.strikeY} L ${scale.getX(allPoints[0].time)} ${scale.strikeY} Z`} fill="url(#greenFill)" stroke="none" />
                            </g>
                            {/* Below Path */}
                            <g clipPath="url(#clipBottom)">
                                <path d={paths.mainPath} fill="none" stroke="#ff375f" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d={`${paths.mainPath} L ${paths.lastX} ${scale.strikeY} L ${scale.getX(allPoints[0].time)} ${scale.strikeY} Z`} fill="url(#redFill)" stroke="none" />
                            </g>

                            {/* LIVE HORIZONTAL PRICE LINE */}
                            <line x1={paths.lastX} y1={paths.lastY} x2={width} y2={paths.lastY} stroke={isAbove ? "#9cfc0d" : "#ff375f"} strokeDasharray="4 4" strokeWidth="1" />

                            {/* Current Price Dot & Label */}
                            <circle cx={paths.lastX} cy={paths.lastY} r="3" fill={isAbove ? "#9cfc0d" : "#ff375f"} stroke="#fff" strokeWidth="1" />
                            <rect x={width - 65} y={paths.lastY - 7} width="65" height="14" fill={isAbove ? "#9cfc0d" : "#ff375f"} rx="2" />
                            <text x={width - 32} y={paths.lastY + 3} textAnchor="middle" fill="#000" fontSize="8.5" fontWeight="950" fontFamily="monospace">
                                {livePrice?.toFixed(2)}
                            </text>
                        </>
                    )}

                    {/* CROSSHAIR & TOOLTIP */}
                    {hoverPoint && mousePos && (
                        <g>
                            <line
                                x1={scale.getX(hoverPoint.time)} y1="0"
                                x2={scale.getX(hoverPoint.time)} y2={height - 60}
                                stroke="rgba(255,255,255,0.3)" strokeDasharray="4 4" strokeWidth="1"
                            />
                            <line
                                x1="0" y1={scale.getY(hoverPoint.value)}
                                x2={scale.availableWidth} y2={scale.getY(hoverPoint.value)}
                                stroke="rgba(255,255,255,0.3)" strokeDasharray="4 4" strokeWidth="1"
                            />

                            <circle
                                cx={scale.getX(hoverPoint.time)}
                                cy={scale.getY(hoverPoint.value)}
                                r="3" fill="#fff"
                            />

                            {/* Tooltip */}
                            <g transform={`translate(${scale.getX(hoverPoint.time) + 12}, ${scale.getY(hoverPoint.value) - 45})`}>
                                <rect
                                    width="100" height="35" rx="6"
                                    fill="rgba(20,20,20,0.95)" stroke="rgba(255,255,255,0.15)" strokeWidth="1"
                                />
                                <text x="10" y="14" fill="rgba(255,255,255,0.5)" fontSize="9" fontFamily="monospace">
                                    {new Date(hoverPoint.time * 1000).getUTCHours().toString().padStart(2, '0')}:
                                    {new Date(hoverPoint.time * 1000).getUTCMinutes().toString().padStart(2, '0')}:
                                    {new Date(hoverPoint.time * 1000).getUTCSeconds().toString().padStart(2, '0')}
                                </text>
                                <text x="10" y="26" fill="#fff" fontSize="10" fontWeight="800" fontFamily="monospace">
                                    ${hoverPoint.value.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                                </text>
                            </g>
                        </g>
                    )}
                </svg>
            )}

            {/* Loading Overlay */}
            {(allPoints.length === 0 || !scale) && (
                <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", color: "rgba(255,255,255,0.15)", fontSize: "11px", fontWeight: 700 }}>
                    CONSTRUCTING SVG TIMELINE...
                </div>
            )}
        </div>
    );
}

import React, { useEffect } from 'react';

interface GeckoWidgetProps {
    coinId: string;
    mini?: boolean;
}

const GeckoWidget: React.FC<GeckoWidgetProps> = ({ coinId, mini = false }) => {
