"use client";

import { useEffect, useRef, useState, useMemo, useCallback } from "react";

interface PricePoint {
    time: number;
    value: number;
}

interface PriceChartProps {
    symbol?: string; // e.g. "BTCUSDT" or "ETHUSDT"
    height?: number;
    startTime?: number;
    endTime?: number;
    bettingEndTime?: number;
    strikePrice?: number;
}

// ΓöÇΓöÇ LocalStorage price cache (fills CCXT lag gap across page refreshes) ΓöÇΓöÇ
const LS_KEY_PREFIX = 'rt_cache_';
const LS_MAX_HOURS = 2;

function loadStoredPrices(symbol: string): PricePoint[] {
    try {
        if (typeof window === 'undefined') return [];
        const raw = localStorage.getItem(LS_KEY_PREFIX + symbol);
        if (!raw) return [];
        const data = JSON.parse(raw) as PricePoint[];
        const cutoff = Math.floor(Date.now() / 1000) - LS_MAX_HOURS * 3600;
        return data.filter(p => p.time > cutoff);
    } catch { return []; }
}

export function PriceChart({ symbol = "BTCUSDT", height = 480, startTime, endTime, bettingEndTime, strikePrice }: PriceChartProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const [width, setWidth] = useState(0);
    const [history, setHistory] = useState<PricePoint[]>([]);
    const [livePrice, setLivePrice] = useState<number | null>(null);
    // Binance WebSocket candles ΓÇö fills CCXT lag gap with real data
    const [wsCandles, setWsCandles] = useState<PricePoint[]>([]);

    // Interactive state
    const [hoverPoint, setHoverPoint] = useState<PricePoint | null>(null);
    const [mousePos, setMousePos] = useState<{ x: number; y: number } | null>(null);

    const actualBettingEndTime = bettingEndTime || (endTime ? endTime - 900 : undefined);

    // We reserve space on the right for the price axis/labels
    const RIGHT_AXIS_WIDTH = 75;

    // Normalize symbol for API (Slash format) vs WebSocket (lowercase combined)
    const apiSymbol = symbol.includes('/') ? symbol : (symbol.replace('USDT', '/USDT'));
    const wsSymbol = symbol.toLowerCase().replace('/', '');

    useEffect(() => {
        if (!containerRef.current) return;
        const observer = new ResizeObserver((entries) => {
            for (const entry of entries) {
                setWidth(entry.contentRect.width);
            }
        });
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        let isMounted = true;
        async function fetchHistory() {
            if (!startTime || !endTime) return;
            try {
                const res = await fetch(`/api/history?symbol=${encodeURIComponent(apiSymbol)}&since=${startTime - 600}`, { cache: "no-store" });
                if (!res.ok) throw new Error("History API failed");
                const data = await res.json();
                const raw = data.history || [];
                const currentNow = Math.floor(Date.now() / 1000);

                const filtered = raw
                    .filter((p: any) => p.time >= (startTime - 3600) && p.time <= Math.min(endTime, currentNow + 60))
                    .sort((a: any, b: any) => a.time - b.time);

                if (isMounted) setHistory(filtered);
            } catch (err) {
                console.error("SVG Chart history error:", err);
            }
        }
        fetchHistory();
        const t = setInterval(fetchHistory, 60000); 
        return () => { isMounted = false; clearInterval(t); };
    }, [startTime, endTime, apiSymbol]);

    useEffect(() => {
        let isMounted = true;
        async function fetchLive() {
            try {
                const res = await fetch(`/api/price?symbol=${encodeURIComponent(apiSymbol)}`, { cache: "no-store" });
                if (res.ok && isMounted) {
                    const data = await res.json();
                    if (data.price > 0) setLivePrice(data.price);
                }
            } catch (k) { }
        }
        fetchLive();
        const t = setInterval(fetchLive, 2000);
        return () => { isMounted = false; clearInterval(t); };
    }, [endTime, startTime, apiSymbol]);

    // ΓöÇΓöÇ Binance REST: fill gap between CCXT history end and now ΓöÇΓöÇ
    useEffect(() => {
        if (!startTime || !endTime) return;
        let isMounted = true;
        async function fillGap() {
            const now = Math.floor(Date.now() / 1000);
            const cleanSymbol = symbol.replace('/', '');
            const limitMinutes = Math.min(Math.floor((now - startTime!) / 60) + 30, 1000);
            try {
                const res = await fetch(
                    `https://api.binance.com/api/v3/klines?symbol=${cleanSymbol}&interval=1m&limit=${limitMinutes}`,
                    { cache: 'no-store' }
                );
                if (!res.ok) return;
                const raw: any[][] = await res.json();
                const candles: PricePoint[] = raw.map(k => ({
                    time: Math.floor(k[0] / 1000),
                    value: parseFloat(k[4]), // close price
                })).filter(p => p.time >= startTime! && p.time <= endTime!);
                if (isMounted) setWsCandles(candles);
            } catch { }
        }
        fillGap();
        const t = setInterval(fillGap, 60000);
        return () => { isMounted = false; clearInterval(t); };
    }, [startTime, endTime, symbol]);

    // ΓöÇΓöÇ Binance WebSocket: update current (open) candle in real-time ΓöÇΓöÇ
    useEffect(() => {
        if (!startTime || !endTime) return;
        const now = Math.floor(Date.now() / 1000);
        if (now > endTime!) return; 
        const ws = new WebSocket(`wss://stream.binance.com:9443/ws/${wsSymbol}@kline_1m`);
        ws.onmessage = (event) => {
            try {
                const data = JSON.parse(event.data);
                const k = data.k;
                if (!k) return;
                const klineStart = Math.floor(Number(k.t) / 1000);
                const closePrice = parseFloat(k.c);
                if (klineStart < startTime! || klineStart > endTime!) return;
                setWsCandles(prev => {
                    const filtered = prev.filter(p => p.time !== klineStart);
                    return [...filtered, { time: klineStart, value: closePrice }]
                        .sort((a, b) => a.time - b.time);
                });
            } catch { }
        };
        ws.onerror = () => ws.close();
        return () => ws.close();
    }, [startTime, endTime, wsSymbol]);

    const allPoints = useMemo(() => {
        const now = Math.floor(Date.now() / 1000);
        const combined = new Map<number, number>();
        history.forEach(p => combined.set(p.time, p.value));
        wsCandles.forEach(p => combined.set(p.time, p.value)); 
        const merged = Array.from(combined.entries())
            .map(([time, value]) => ({ time, value }))
            .filter(p => p.time >= (startTime ?? 0) && p.time <= Math.min(endTime ?? now, now))
            .sort((a, b) => a.time - b.time);

        const lastTime = merged.length > 0 ? merged[merged.length - 1].time : 0;
        if (livePrice && startTime && now <= (endTime ?? now + 1) && now > lastTime) {
            merged.push({ time: now, value: livePrice });
        }
        return merged;
    }, [history, wsCandles, livePrice, startTime, endTime]);

    const scale = useMemo(() => {
        if (!startTime || !endTime || !width || !strikePrice) return null;

        const prices = allPoints.map(p => p.value);
        const midP = strikePrice;

        const maxDelta = prices.length > 0 ? Math.max(...prices.map(p => Math.abs(p - midP))) : midP * 0.01;
        const rawBuffer = Math.max(maxDelta * 1.15, midP * 0.01);
        const buffer = rawBuffer;

        const minScale = midP - buffer;
        const maxScale = midP + buffer;

        const availableWidth = width - RIGHT_AXIS_WIDTH;
        const getX = (t: number) => ((t - startTime) / (endTime - startTime)) * availableWidth;

        const paddingY = 70;
        const chartAreaH = height - paddingY * 2 - 40;
        const getY = (p: number) => paddingY + chartAreaH - ((p - minScale) / (maxScale - minScale)) * chartAreaH;

        return { getX, getY, minScale, maxScale, midP, strikeY: getY(midP), availableWidth };
    }, [allPoints, startTime, endTime, width, height, strikePrice, RIGHT_AXIS_WIDTH]);

    const paths = useMemo(() => {
        if (!scale || allPoints.length === 0) return null;

        let d = `M ${scale.getX(allPoints[0].time)} ${scale.getY(allPoints[0].value)}`;
        for (let i = 1; i < allPoints.length; i++) {
            const x = scale.getX(allPoints[i].time);
            const y = scale.getY(allPoints[i].value);
            if (!isNaN(x) && !isNaN(y)) {
                d += ` L ${x} ${y}`;
            }
        }

        const lastX = scale.getX(allPoints[allPoints.length - 1].time);
        const lastY = scale.getY(allPoints[allPoints.length - 1].value);

        return { mainPath: d, lastX, lastY };
    }, [allPoints, scale]);

    const handleMouseMove = useCallback((e: React.MouseEvent<SVGSVGElement>) => {
        if (!scale || allPoints.length === 0 || !containerRef.current) return;

        const rect = containerRef.current.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        if (x > scale.availableWidth) return;

        let nearest = allPoints[0];
        let minDist = Math.abs(scale.getX(allPoints[0].time) - x);

        for (let i = 1; i < allPoints.length; i++) {
            const dist = Math.abs(scale.getX(allPoints[i].time) - x);
            if (dist < minDist) {
                minDist = dist;
                nearest = allPoints[i];
            }
        }

        setHoverPoint(nearest);
        setMousePos({ x, y });
    }, [allPoints, scale]);

    const handleMouseLeave = useCallback(() => {
        setHoverPoint(null);
        setMousePos(null);
    }, []);

    if (!startTime || !endTime || !strikePrice) return null;

    const isAbove = livePrice !== null && strikePrice !== undefined && livePrice > strikePrice;

    return (
        <div ref={containerRef} style={{
            display: "flex", flexDirection: "column", width: "100%", height: `${height}px`,
            background: "#0a0a0a", borderRadius: "12px", border: "1px solid rgba(255,255,255,0.05)",
            position: "relative", overflow: "hidden"
        }}>
            <div style={{
                position: "absolute", top: "16px", left: "20px", right: "20px",
                display: "flex", justifyContent: "space-between", alignItems: "center",
                zIndex: 50, pointerEvents: "none"
            }}>
                <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
                    <span style={{ fontSize: "14px", fontWeight: 700, color: "#fff" }}>{apiSymbol.replace("/USDT", "/USD")}</span>
                    <span style={{ fontSize: "14px", color: "rgba(255,255,255,0.2)" }}>ΓÇó</span>
                    <span style={{ fontSize: "10px", color: "#9cfc0d", fontWeight: 700 }}>LIVE</span>
                    <span style={{
                        fontSize: "10px",
                        background: isAbove ? "rgba(156,252,13,0.1)" : "rgba(255, 45, 85, 0.1)",
                        color: isAbove ? "#9cfc0d" : "#ff375f",
                        padding: "3px 8px", borderRadius: "4px", fontWeight: 900,
                        border: isAbove ? "1px solid rgba(156,252,13,0.3)" : "1px solid rgba(255, 45, 85, 0.3)"
                    }}>
                        {isAbove ? "ABOVE" : "BELOW"}
                    </span>
                </div>

                <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
                    <div style={{ fontSize: "13px" }}>
                        <span style={{ color: "rgba(255,255,255,0.6)", fontWeight: 500 }}>Current</span> <span style={{ fontFamily: "monospace", color: "#fff", fontWeight: 800, fontSize: "16px" }}>${livePrice?.toLocaleString(undefined, { minimumFractionDigits: (livePrice ?? 0) < 1 ? 4 : 2 })}</span>
                    </div>
                </div>
            </div>

            {width > 0 && scale && (
                <svg
                    width={width}
                    height={height}
                    style={{ display: "block", cursor: "crosshair" }}
                    onMouseMove={handleMouseMove}
                    onMouseLeave={handleMouseLeave}
                >
                    <defs>
                        <linearGradient id="greenFill" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#9cfc0d" stopOpacity="0.1" />
                            <stop offset="100%" stopColor="#9cfc0d" stopOpacity="0" />
                        </linearGradient>
                        <linearGradient id="redFill" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#ff375f" stopOpacity="0" />
                            <stop offset="100%" stopColor="#ff375f" stopOpacity="0.1" />
                        </linearGradient>

                        <clipPath id="clipTop">
                            <rect x="0" y="0" width={scale.availableWidth} height={scale.strikeY} />
                        </clipPath>
                        <clipPath id="clipBottom">
                            <rect x="0" y={scale.strikeY} width={scale.availableWidth} height={height - scale.strikeY} />
                        </clipPath>
                    </defs>

                    {[0, 0.25, 0.5, 0.75, 1].map((f, i) => {
                        const y = 70 + f * (height - 180);
                        const price = scale.maxScale - f * (scale.maxScale - scale.minScale);
                        return (
                            <g key={i}>
                                <line x1="0" y1={y} x2={scale.availableWidth} y2={y} stroke="rgba(255,255,255,0.03)" />
                                <text x={width - 10} y={y + 3} textAnchor="end" fill="rgba(255,255,255,0.15)" fontSize="9" fontFamily="monospace">
                                    {price < 1 ? price.toFixed(4) : Math.round(price)}
                                </text>
                            </g>
                        );
                    })}

                    {[startTime, Math.floor((startTime + endTime) / 2), endTime].map((t, i) => {
                        const x = scale.getX(t);
                        const date = new Date(t * 1000);
                        const h = date.getUTCHours().toString().padStart(2, '0');
                        const m = date.getUTCMinutes().toString().padStart(2, '0');
                        return (
                            <text key={i} x={x} y={height - 25} textAnchor={i === 0 ? "start" : i === 2 ? "end" : "middle"} fill="rgba(255,255,255,0.3)" fontSize="10" fontFamily="monospace">
                                {`${h}:${m}`}
                            </text>
                        );
                    })}

                    <line x1="0" y1={scale.strikeY} x2={width} y2={scale.strikeY} stroke="#00ccff" strokeDasharray="4 4" strokeWidth="1" />
                    <rect x={width - 65} y={scale.strikeY - 7} width="65" height="14" fill="#00ccff" rx="2" />
                    <text x={width - 32} y={scale.strikeY + 3} textAnchor="middle" fill="#000" fontSize="8.5" fontWeight="950" fontFamily="monospace">
                        {strikePrice < 1 ? strikePrice.toFixed(4) : strikePrice.toFixed(2)}
                    </text>
                    <text x={width - 7} y={scale.strikeY - 11} textAnchor="end" fill="#00ccff" fontSize="8" fontWeight="800">Target</text>

                    {actualBettingEndTime && (
                        <g>
                            <line x1={scale.getX(actualBettingEndTime)} y1="0" x2={scale.getX(actualBettingEndTime)} y2={height - 60} stroke="rgba(245, 158, 11, 0.4)" strokeDasharray="3 3" />
                            <text
                                x={scale.getX(actualBettingEndTime)}
                                y={height - 45}
                                textAnchor="middle"
                                fill="#f59e0b"
                                fontSize="10"
                                fontFamily="monospace"
                                fontWeight="700"
                            >
                                {(() => {
                                    const d = new Date(actualBettingEndTime * 1000);
                                    return `${d.getUTCHours().toString().padStart(2, '0')}:${d.getUTCMinutes().toString().padStart(2, '0')}`;
                                })()}
                            </text>
                            <text
                                x={scale.getX(actualBettingEndTime)}
                                y={height - 35}
                                textAnchor="middle"
                                fill="rgba(245, 158, 11, 0.6)"
                                fontSize="8"
                                fontFamily="sans-serif"
                                fontWeight="900"
                            >
                                BETTING CLOSE TIME
                            </text>
                        </g>
                    )}

                    {paths && (
                        <>
                            <g clipPath="url(#clipTop)">
                                <path d={paths.mainPath} fill="none" stroke="#9cfc0d" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d={`${paths.mainPath} L ${paths.lastX} ${scale.strikeY} L ${scale.getX(allPoints[0].time)} ${scale.strikeY} Z`} fill="url(#greenFill)" stroke="none" />
                            </g>
                            <g clipPath="url(#clipBottom)">
                                <path d={paths.mainPath} fill="none" stroke="#ff375f" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
                                <path d={`${paths.mainPath} L ${paths.lastX} ${scale.strikeY} L ${scale.getX(allPoints[0].time)} ${scale.strikeY} Z`} fill="url(#redFill)" stroke="none" />
                            </g>

                            <line x1={paths.lastX} y1={paths.lastY} x2={width} y2={paths.lastY} stroke={isAbove ? "#9cfc0d" : "#ff375f"} strokeDasharray="4 4" strokeWidth="1" />

                            <circle cx={paths.lastX} cy={paths.lastY} r="3" fill={isAbove ? "#9cfc0d" : "#ff375f"} stroke="#fff" strokeWidth="1" />
                            <rect x={width - 65} y={paths.lastY - 7} width="65" height="14" fill={isAbove ? "#9cfc0d" : "#ff375f"} rx="2" />
                            <text x={width - 32} y={paths.lastY + 3} textAnchor="middle" fill="#000" fontSize="8.5" fontWeight="950" fontFamily="monospace">
                                {livePrice !== null ? (livePrice < 1 ? livePrice.toFixed(4) : livePrice.toFixed(2)) : "0.00"}
                            </text>
                        </>
                    )}

                    {hoverPoint && mousePos && (
                        <g>
                            <line
                                x1={scale.getX(hoverPoint.time)} y1="0"
                                x2={scale.getX(hoverPoint.time)} y2={height - 60}
                                stroke="rgba(255,255,255,0.3)" strokeDasharray="4 4" strokeWidth="1"
                            />
                            <line
                                x1="0" y1={scale.getY(hoverPoint.value)}
                                x2={scale.availableWidth} y2={scale.getY(hoverPoint.value)}
                                stroke="rgba(255,255,255,0.3)" strokeDasharray="4 4" strokeWidth="1"
                            />

                            <circle
                                cx={scale.getX(hoverPoint.time)}
                                cy={scale.getY(hoverPoint.value)}
                                r="3" fill="#fff"
                            />

                            <g transform={`translate(${scale.getX(hoverPoint.time) + 12}, ${scale.getY(hoverPoint.value) - 45})`}>
                                <rect
                                    width="100" height="35" rx="6"
                                    fill="rgba(20,20,20,0.95)" stroke="rgba(255,255,255,0.15)" strokeWidth="1"
                                />
                                <text x="10" y="14" fill="rgba(255,255,255,0.5)" fontSize="9" fontFamily="monospace">
                                    {new Date(hoverPoint.time * 1000).getUTCHours().toString().padStart(2, '0')}:
                                    {new Date(hoverPoint.time * 1000).getUTCMinutes().toString().padStart(2, '0')}:
                                    {new Date(hoverPoint.time * 1000).getUTCSeconds().toString().padStart(2, '0')}
                                </text>
                                <text x="10" y="26" fill="#fff" fontSize="10" fontWeight="800" fontFamily="monospace">
                                    ${hoverPoint.value.toLocaleString(undefined, { minimumFractionDigits: hoverPoint.value < 1 ? 4 : 2 })}
                                </text>
                            </g>
                        </g>
                    )}
                </svg>
            )}

            {(allPoints.length === 0 || !scale) && (
                <div style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%, -50%)", color: "rgba(255,255,255,0.15)", fontSize: "11px", fontWeight: 700 }}>
                    CONSTRUCTING SVG TIMELINE...
                </div>
            )}
        </div>
    );
}

import React, { useState } from 'react';
import styles from './TradeBox.module.css';
import { MarketData, getUserMarketStatus, UserMarketStatus } from '../../../data/markets';
import { claimRewards, placeBet, checkUsdlBalance, isRouterApproved, approveRouter } from '../../../lib/onchain/writes';
import { useWallet } from '../../providers/WalletProvider';
import { useToast } from '../../providers/ToastProvider';
import ConnectWalletPrompt from '../Wallet/ConnectWalletPrompt';
import { readContract } from 'wagmi/actions';
import { wagmiConfig } from '../../../lib/onchain/wagmiConfig';
import { seismicTestnet } from '../../../lib/onchain/seismicChain';
import { TOKEN_ADDRESS, SKYUSD_MULTIPLIER, SKYUSD_ABI, TOKEN_SYMBOL } from '../../../lib/constants';

interface TradeBoxProps {
    probability: number;
    market?: MarketData;
}

const TradeBox: React.FC<TradeBoxProps> = ({ probability: _probability, market }) => {
    void _probability;
    const [amount, setAmount] = useState<string>('');
    const [selectedOutcome, setSelectedOutcome] = useState<'YES' | 'DRAW' | 'NO'>('YES');
    const [tokenBalance, setTokenBalance] = React.useState<bigint | undefined>(undefined);
    const [isPlacingBet, setIsPlacingBet] = React.useState(false);
    const [routerApproved, setRouterApproved] = React.useState(false);
    const [isApproving, setIsApproving] = React.useState(false);

    const { isConnected, walletAddress, connect, isConnecting } = useWallet();
    const { showToast } = useToast();

    const fetchTokenBalance = React.useCallback(async () => {
        if (!walletAddress || !isConnected) {
            setTokenBalance(undefined);
            return;
        }

        try {
            const balance = await readContract(wagmiConfig, {
                chainId: seismicTestnet.id,
                address: TOKEN_ADDRESS as `0x${string}`,
                abi: SKYUSD_ABI,
                functionName: 'balanceOf',
                args: [walletAddress as `0x${string}`]
            });
            setTokenBalance(balance);
        } catch (error) {
            console.error('Failed to fetch token balance:', error);
            setTokenBalance(undefined);
        }
    }, [walletAddress, isConnected]);

    React.useEffect(() => {
        fetchTokenBalance();
    }, [fetchTokenBalance]);

    // Check router approval status
    React.useEffect(() => {
        if (!walletAddress || !isConnected) {
            setRouterApproved(false);
            return;
        }
        isRouterApproved(walletAddress as `0x${string}`)
            .then(setRouterApproved)
            .catch(() => setRouterApproved(false));
    }, [walletAddress, isConnected]);

    const [userStatus, setUserStatus] = React.useState<UserMarketStatus | null>(null);

    React.useEffect(() => {
        const fetchUserStatus = async () => {
            if (market && isConnected && walletAddress && market.contractId) {
                try {
                    const status = await getUserMarketStatus(market.contractId, walletAddress, market);
                    setUserStatus(status);
                } catch (error) {
                    console.error('Error fetching user status:', error);
                    setUserStatus(null);
                }
            } else {
                setUserStatus(null);
            }
        };

        fetchUserStatus();
    }, [market, isConnected, walletAddress]);

    const handleClaim = async () => {
        if (!market) return;
        try {
            await claimRewards(market.contractId as `0x${string}`);
            showToast('Rewards claimed successfully!', 'success');
            fetchTokenBalance();
        } catch (error) {
            console.error('Failed to claim rewards:', error);
            showToast('Failed to claim rewards. Please try again.', 'error');
        }
    };

    const numericAmount = parseFloat(amount) || 0;
    const amountInUnits = BigInt(Math.floor(numericAmount * SKYUSD_MULTIPLIER));
    const insufficientBalance = tokenBalance ? tokenBalance < amountInUnits : false;

    if (market) {
        if (market.state === 'RESOLVED' || market.state === 'UNDETERMINED') {
            if (!isConnected) {
                return (
                    <div className={styles.tradeBox}>
                        <div className={styles.subtleHeader}>
                            <span className={styles.marketStatus}>Market Resolved</span>
                            <span className={`${styles.outcomeTag} ${market.resolvedOutcome === market.sideAName ? styles.outcomeYes : styles.outcomeNo}`}>
                                {market.resolvedOutcome} Won
                            </span>
                        </div>
                        <ConnectWalletPrompt align="left" message="Connect your wallet to start betting." />
                    </div>
                );
            }
            return (
                <div className={styles.tradeBox}>
                    <div className={styles.subtleHeader}>
                        <span className={styles.marketStatus}>Market Resolved</span>
                        <span className={`${styles.outcomeTag} ${market.resolvedOutcome === market.sideAName ? styles.outcomeYes : styles.outcomeNo}`}>
                            {market.resolvedOutcome} Won
                        </span>
                    </div>

                    {userStatus?.hasPosition ? (
                        <div className={styles.positionSummary}>
                            <div className={styles.positionRow}>
                                <span>Your bet:</span>
                                <span>{userStatus.position!.amount} {TOKEN_SYMBOL} on {userStatus.position!.outcome}</span>
                            </div>
                            {userStatus.userWon ? (
                                <div className={styles.positionRow}>
                                    <span>You won:</span>
                                    <span className={styles.winAmount}>+{userStatus.potentialWinnings.toFixed(0)} {TOKEN_SYMBOL}</span>
                                </div>
                            ) : (
                                <div className={styles.positionRow}>
                                    <span className={styles.lossText}>You lost your bet</span>
                                </div>
                            )}
                            {userStatus.canClaim && (
                                <button className={styles.claimButton} onClick={handleClaim}>
                                    Claim {userStatus.potentialWinnings.toFixed(0)} {TOKEN_SYMBOL}
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className={styles.noPosition}>
                            <p>You did not bet on this market.</p>
                        </div>
                    )}
                </div>
            );
        }

        if (market.state === 'RESOLVING') {
            if (!isConnected) {
                return (
                    <div className={styles.tradeBox}>
                        <div className={styles.subtleHeader}>
                            <span className={styles.marketStatus}>Resolving...</span>
                            <div className={styles.loadingDot}></div>
                        </div>
                        <ConnectWalletPrompt align="left" message="Connect your wallet to start betting." />
                    </div>
                );
            }
            return (
                <div className={styles.tradeBox}>
                    <div className={styles.subtleHeader}>
                        <span className={styles.marketStatus}>Resolving...</span>
                        <div className={styles.loadingDot}></div>
                    </div>

                    {userStatus?.hasPosition && (
                        <div className={styles.positionSummary}>
                            <div className={styles.positionRow}>
                                <span>Your bet:</span>
                                <span>{userStatus.position!.amount} {TOKEN_SYMBOL} on {userStatus.position!.outcome}</span>
                            </div>
                            <p className={styles.waitingText}>Waiting for resolution...</p>
                        </div>
                    )}
                </div>
            );
        }

        if (userStatus?.hasPosition) {
            return (
                <div className={styles.tradeBox}>
                    <div className={styles.positionSummary}>
                        <div className={styles.positionRow}>
                            <span>Current bet:</span>
                            <span>{userStatus.position!.amount} {TOKEN_SYMBOL} on {userStatus.position!.outcome}</span>
                        </div>
                    </div>

                    <div className={styles.divider}></div>
                    {renderTradingInterface()}
                </div>
            );
        }
    }

    if (!isConnected) {
        return (
            <div className={styles.tradeBox}>
                <ConnectWalletPrompt align="left" message="Connect your wallet to start betting." />
            </div>
        );
    }

    return <div className={styles.tradeBox}>{renderTradingInterface()}</div>;

    function renderTradingInterface() {
        return (
            <>
                <div className={styles.inputGroup}>
                    <div className={styles.inputLabel}>
                        <span>1.</span> Enter amount
                        <span className={styles.pctOptions}>
                            <span onClick={() => setAmount('10')}>10$</span>
                            <span onClick={() => setAmount('20')}>20$</span>
                            <span onClick={() => setAmount('50')}>50$</span>
                            {tokenBalance !== undefined && (
                                <span onClick={() => setAmount((Number(tokenBalance) / SKYUSD_MULTIPLIER).toFixed(2))}>Max</span>
                            )}
                        </span>
                    </div>
                    <div className={styles.amountInputContainer}>
                        <input
                            type="number"
                            className={styles.amountInput}
                            placeholder="0"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                        />
                        <span className={styles.usdcSuffix}>{TOKEN_SYMBOL}</span>
                    </div>
                    {tokenBalance !== undefined ? (
                        <div
                            style={{
                                fontSize: '11px',
                                color: 'var(--text-secondary)',
                                marginTop: '4px',
